A stack is a linear data structure that follows the Last In First Out (LIFO) principle. This means that the element added last in the stack will be the one to be removed first. Here's an implementation of a stack data structure using an array in JavaScript:

```javascript
class Stack{
    constructor(){
        this.items = []
        this.top = null
    }

    push(element){
        this.items.push(element)
        this.top = element
    }

    pop(){
        if(this.items.length !=0){
            if(this.items.length == 1){
                this.top = null
                return this.items.pop()
            }else{
                this.top = this.items[this.items.length -2]
                return this.items.pop()
            }

        }else
            return null
    }

    getTop(){
        return this.top
    }

    isEmpty(){
        return this.items.length == 0
    }

    size(){
        return this.items.length
    }
}

let myStack = new Stack()
myStack.push(1)
myStack.push(2)
myStack.push(3)
console.log(myStack.pop()) // 3
console.log(myStack.getTop()) // 2
console.log(myStack.pop()) // 2
console.log(myStack.getTop()) // 1
console.log(myStack.isEmpty()) // false
console.log(myStack.pop()) // 1
console.log(myStack.isEmpty()) // true
``` 

